SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(STDDEV(rating), 2) AS stddev_rating, ROUND((100 * SUM(CASE WHEN city = 'Tokyo' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_tokyo, COUNT(*) AS num_suppliers FROM suppliers WHERE supplier_name LIKE '%Glob%' GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END ORDER BY num_suppliers DESC;
